    void cleanupOldEntriesInternal() noexcept {
        auto now = std::chrono::steady_clock::now();
        auto cutoffTime = now - m_cacheTTL;

        // Remove entries older than TTL
        for (auto it = m_cacheEntries.begin(); it != m_cacheEntries.end();) {
